import React, { useState } from 'react';
import { Stat, PageTitle, Field, Modal, Status, Empty } from '../../components/common';
import './ProjectsPage.css';

export default function ProjectsPage({properties}) { const groups=[...new Set(properties.map(p=>p.location))]; return <div className="module-page module-page--projects"><PageTitle eyebrow="DEVELOPMENT TRACKER" title="Projects" subtitle="A location-wise overview of the inventory your team is handling."/><div className="stats-grid"><Stat label="Projects / locations" value={groups.length} change="Distinct locations" icon="▤" tone="purple" foot="Based on current inventory"/><Stat label="Available inventory" value={properties.filter(p=>p.status==='Available').length} change="Can be offered" icon="⌂" tone="green" foot="Availability from demo data"/><Stat label="On hold" value={properties.filter(p=>p.status==='On Hold').length} change="Needs verification" icon="◷" tone="orange" foot="Confirm before pitching"/><Stat label="Total listings" value={properties.length} change="Across workspace" icon="▦" tone="blue" foot="All property records"/></div><div className="project-grid">{groups.map((g,i)=><div className="panel project-card" key={g}><div className={`project-icon pi-${i%3}`}>⌂</div><div><h3>{g}</h3><p>{properties.filter(p=>p.location===g).length} listing(s) in this area</p></div><div className="project-list">{properties.filter(p=>p.location===g).map(p=><div key={p.id}><span>{p.name}</span><b>{money(p.price)}</b></div>)}</div></div>)}</div></div>; }
